<script lang="ts">
	import { SYSTEMS } from '#lib/calculation/production-engine';
	import { Boxes, ChevronRight, Factory, GlassWater, Ruler, Search } from '@lucide/svelte';
	let selected=$state(SYSTEMS[0].code),query=$state('');
	const recipes:Record<string,string[]>={KATLANIR_8MM:['Gold üst kasa 1250','Damlalıklı alt kasa 1303','Baza 8 mm','Yan dikme','Teker ve makas seti'],KATLANIR_OVAL:['Oval üst kasa','Oval alt kasa','Oval baza','Yan dikme','Oval H fitil'],KATLANIR_ISICAM:['Isıcam alt-üst kasa','Isıcam baza','Yan dikme','Kollu fitil','Kilit profili'],SURME_GOLD_8MM:['Sürme üst kasa','Alt ray','Üst kanat','Alt kanat','Yan çıta'],SURME_ISICAM:['5li sürme kasa 1165','Eşikli ray 1164','Üst kanat 1169','Alt kanat 1167','Yan çıta 1171'],GIYOTIN:['Giyotin kasa','Alt kasa 1261','Dikey kızak','Kanat profili','Motor ve emniyet seti'],ALDOX:['Geniş kasa 1106','Geniş kanat 1104','Orta kayıt 1105','Cam çıtası','Kol, kilit ve menteşe']};
	function current(){return SYSTEMS.find(x=>x.code===selected)??SYSTEMS[0]}
	function visible(){return SYSTEMS.filter(x=>`${x.name} ${x.description}`.toLocaleLowerCase('tr-TR').includes(query.toLocaleLowerCase('tr-TR')))}
	const money=(n:number)=>n.toLocaleString('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:0});
</script>
<svelte:head><title>Ürün Kataloğu | Tayfun Yapı</title></svelte:head>
<div class="page"><header><div><span>ATÖLYE</span><h1>Ürün Kataloğu</h1><p>Sistem reçeteleri, teknik düşümler ve üretim başlangıç değerleri.</p></div><a href={`/wizard?system=${selected}`}>Bu sistemle yeni iş <ChevronRight size={17}/></a></header><div class="layout"><aside><label><Search size={16}/><input bind:value={query} placeholder="Sistem ara"/></label>{#each visible() as system}<button class:active={system.code===selected} onclick={()=>selected=system.code}><span>{#if system.kind==='sliding'}<Ruler/>{:else if system.kind==='guillotine'}<Factory/>{:else if system.kind==='aldox'}<Boxes/>{:else}<GlassWater/>{/if}</span><div><strong>{system.name}</strong><small>{system.description}</small></div><ChevronRight size={17}/></button>{/each}</aside><main><div class="system-head"><div class="icon"><Factory size={28}/></div><div><span>{current().code}</span><h2>{current().name}</h2><p>{current().description}</p></div></div><section class="specs"><div><span>Varsayılan cam</span><strong>{current().glassType}</strong></div><div><span>Hedef kanat eni</span><strong>{current().panelWidth} mm</strong></div><div><span>Cam yan düşümü</span><strong>{current().glassSideDeduction} mm</strong></div><div><span>Cam boy düşümü</span><strong>{current().glassHeightDeduction} mm</strong></div><div><span>Başlangıç fiyatı</span><strong>{money(current().pricePerM2)} / m²</strong></div></section><section class="recipe"><h3><Boxes size={18}/>Malzeme reçetesi</h3>{#each recipes[selected]||[] as item,index}<div><span>{String(index+1).padStart(2,'0')}</span><strong>{item}</strong><em>{index<3?'Profil':'Aksesuar'}</em></div>{/each}</section><section class="rules"><h3>Üretim kuralları</h3><ul><li>Kanat sayısı genişliğe göre otomatik hesaplanır ve elle değiştirilebilir.</li><li>Cam ölçüsü sistemin yan ve yükseklik düşümleri kullanılarak hazırlanır.</li><li>Profil parçaları 6.500 mm standart boylara testere payıyla yerleştirilir.</li><li>Cam, kesim, boy optimizasyonu ve aksesuar listesi tek iş dosyasında saklanır.</li></ul></section></main></div></div>
